package com.bedlessfighter.necroManager.commands;
import com.bedlessfighter.necroManager.managers.MessageManager; import com.bedlessfighter.necroManager.managers.PermissionManager; import org.bukkit.command.*; import org.bukkit.entity.Player; import org.jetbrains.annotations.NotNull;
public final class DayCommand implements CommandExecutor { public boolean onCommand(@NotNull CommandSender s,@NotNull Command c,@NotNull String @NotNull [] a){if(a.length!=0){MessageManager.sendRaw(s,MessageManager.prefix()+" &cUsage: /day");return true;}if(!PermissionManager.has(s,"necromanager.world")){MessageManager.send(s,"messages.no-perm","&cYou don't have enough permissions to issue this command!");return true;}if(!(s instanceof Player p)){MessageManager.send(s,"messages.player-required","&cConsole must specify a world (not supported yet).");return true;}p.getWorld().setTime(1000);p.getWorld().setStorm(false);p.getWorld().setThundering(false);MessageManager.send(s,"messages.day","&aSet this world to day.");return true;} }